import React, { useState, useEffect } from "react";
import Product from "./Product";

// Kho dữ liệu ảo đã được bổ sung trường "brand" (Thương hiệu)
const mockProductsFromMySQL = [
  { id: 1, name: "PC Gaming Shark i5 13400F | RTX 4060", price: 18500000, category: "PC_Gaming", brand: "Khac", image_url: "", percent_off: 10 },
  { id: 2, name: "PC Đồ Họa Đua Xe AMD Ryzen 7 5700X", price: 16900000, category: "PC_Gaming", brand: "Khac", image_url: "", percent_off: 5 },
  { id: 3, name: "PC Văn Phòng Intel Core i3 12100", price: 6500000, category: "PC_VanPhong", brand: "Intel", image_url: "", percent_off: 0 },
  { id: 5, name: "Laptop Asus Vivobook 14 X1404ZA i5", price: 14290000, category: "Laptop", brand: "Asus", image_url: "", percent_off: 5 },
  { id: 6, name: "Laptop MacBook Air M2 8GB/256GB", price: 24990000, category: "Laptop", brand: "Apple", image_url: "", percent_off: 0 },
  { id: 7, name: "CPU Intel Core i5-14600K", price: 8490000, category: "LinhKien", brand: "Intel", image_url: "", percent_off: 8 },
  { id: 9, name: "Mainboard ASUS ROG STRIX B760-F", price: 5890000, category: "LinhKien", brand: "Asus", image_url: "", percent_off: 0 },
  { id: 13, name: "RAM Corsair Vengeance LPX 16GB", price: 1150000, category: "LinhKien", brand: "Corsair", image_url: "", percent_off: 15 },
  { id: 15, name: "Ổ Cứng SSD Samsung 990 PRO 1TB", price: 2850000, category: "LinhKien", brand: "Samsung", image_url: "", percent_off: 7 },
  { id: 16, name: "Màn Hình Gaming MSI Optix G241V", price: 3290000, category: "ManHinh", brand: "MSI", image_url: "", percent_off: 12 },
  { id: 18, name: "Chuột Không Dây Logitech MX Master 3S", price: 2350000, category: "GamingGear", brand: "Logitech", image_url: "", percent_off: 5 },
  { id: 19, name: "Bàn Phím Cơ ASUS ROG Strix Scope", price: 3150000, category: "GamingGear", brand: "Asus", image_url: "", percent_off: 20 }
];

// Cây danh mục Sidebar
const menuCategories = [
  { id: "PC_ChuyenDung", name: "PC Chuyên Dụng" },
  { id: "PC_Gaming", name: "PC Gaming, Học Tập" },
  { id: "PC_VanPhong", name: "PC Văn Phòng" },
  { id: "Laptop", name: "Laptop - Notebook" },
  { id: "LinhKien", name: "Linh Kiện Máy Tính" },
  { id: "ManHinh", name: "Màn Hình Máy Tính" },
  { id: "GamingGear", name: "Gaming Gear" },
  { id: "PhuKien", name: "Phụ kiện & Dụng cụ" }
];

function ProductList() {
  const [filteredProducts, setFilteredProducts] = useState([]);
  
  // Trạng thái cho Bộ lọc ngang
  const [category, setCategory] = useState("");
  const [brand, setBrand] = useState("");
  const [priceRange, setPriceRange] = useState("");
  
  // Phân trang
  const [currentPage, setCurrentPage] = useState(0); 
  const productsPerPage = 8; 

  // Logic xử lý lọc nhiều điều kiện
  const filterMockData = () => {
    const filtered = mockProductsFromMySQL.filter((item) => {
      // 1. Lọc theo Danh mục
      const matchCategory = category === "" || item.category === category;
      
      // 2. Lọc theo Thương hiệu
      const matchBrand = brand === "" || item.brand === brand;
      
      // 3. Lọc theo Mức giá
      let matchPrice = true;
      if (priceRange === "duoi10") matchPrice = item.price < 10000000;
      else if (priceRange === "10den20") matchPrice = item.price >= 10000000 && item.price <= 20000000;
      else if (priceRange === "tren20") matchPrice = item.price > 20000000;

      return matchCategory && matchBrand && matchPrice;
    });

    setFilteredProducts(filtered);
    setCurrentPage(0); 
  };

  useEffect(() => {
    filterMockData();
  }, [category, brand, priceRange]);

  // Tính toán phân trang
  const indexOfLastProduct = (currentPage + 1) * productsPerPage;
  const indexOfFirstProduct = indexOfLastProduct - productsPerPage;
  const currentProductsToShow = filteredProducts.slice(indexOfFirstProduct, indexOfLastProduct);
  const totalPages = Math.ceil(filteredProducts.length / productsPerPage);

  return (
    <div className="container-fluid mt-4 mb-5 px-4">
      
      {/* --- HEADER BỘ LỌC SẢN PHẨM --- */}
      <div className="row mb-4">
        <div className="col-12">
          {/* Tiêu đề có vạch kẻ dọc */}
          <h4 className="fw-bold text-uppercase mb-3" style={{ borderLeft: "5px solid #000080", paddingLeft: "10px", color: "#000" }}>
            Tất cả sản phẩm
          </h4>
          <p className="text-muted mb-2">Bộ lọc sản phẩm</p>
          
          {/* 3 Nút Dropdown lọc dữ liệu */}
          <div className="d-flex gap-3">
            <select className="form-select w-auto shadow-sm" value={priceRange} onChange={(e) => setPriceRange(e.target.value)}>
              <option value="">Chọn mức giá</option>
              <option value="duoi10">Dưới 10 triệu</option>
              <option value="10den20">Từ 10 - 20 triệu</option>
              <option value="tren20">Trên 20 triệu</option>
            </select>

            <select className="form-select w-auto shadow-sm" value={category} onChange={(e) => setCategory(e.target.value)}>
              <option value="">Loại</option>
              {menuCategories.map(menu => (
                <option key={menu.id} value={menu.id}>{menu.name}</option>
              ))}
            </select>

            <select className="form-select w-auto shadow-sm" value={brand} onChange={(e) => setBrand(e.target.value)}>
              <option value="">Thương hiệu</option>
              <option value="Apple">Apple</option>
              <option value="Asus">Asus</option>
              <option value="Samsung">Samsung</option>
              <option value="Intel">Intel</option>
              <option value="MSI">MSI</option>
              <option value="Logitech">Logitech</option>
            </select>
          </div>
        </div>
      </div>

      <div className="row">
        {/* === SIDEBAR TRÁI (Được làm gọn gàng hơn) === */}
        <div className="col-md-3 mb-4">
          <div className="card shadow-sm border-0 rounded-0">
            <div className="list-group list-group-flush">
              <button
                type="button"
                className={`list-group-item list-group-item-action fw-bold py-2 ${category === "" ? "text-primary" : "text-dark"}`}
                onClick={() => setCategory("")}
              >
                Tất cả sản phẩm
              </button>
              
              {menuCategories.map((menu) => (
                <button
                  key={menu.id}
                  type="button"
                  // Giảm padding (py-1), tăng độ nhỏ gọn
                  className={`list-group-item list-group-item-action border-0 py-1 d-flex justify-content-between align-items-center ${category === menu.id ? "text-primary fw-bold" : "text-muted"}`}
                  onClick={() => setCategory(menu.id)}
                  style={{ fontSize: "15px" }}
                >
                  <span>{menu.name}</span>
                  <small>›</small>
                </button>
              ))}
            </div>
          </div>
        </div>

        {/* === LƯỚI SẢN PHẨM BÊN PHẢI === */}
        <div className="col-md-9 d-flex flex-column justify-content-between">
          <div>
            <div className="row row-cols-1 row-cols-md-2 row-cols-lg-4 g-4">
              {currentProductsToShow.length > 0 ? (
                currentProductsToShow.map((item) => (
                  <Product key={item.id} data={item} />
                ))
              ) : (
                <div className="col-12 text-center mt-5">
                  <p className="text-muted fs-5">Không có sản phẩm nào khớp với bộ lọc của bạn.</p>
                </div>
              )}
            </div>
          </div>

          {/* === PHÂN TRANG (PAGINATION DOTS) === */}
          {totalPages > 1 && (
            <div className="d-flex justify-content-center align-items-center gap-2 mt-5">
              {[...Array(totalPages)].map((_, index) => (
                <button
                  key={index}
                  type="button"
                  onClick={() => setCurrentPage(index)}
                  style={{
                    width: index === currentPage ? "30px" : "10px",
                    height: "10px",
                    borderRadius: "5px",
                    border: "none",
                    backgroundColor: index === currentPage ? "#000080" : "#cccccc",
                    transition: "all 0.3s ease",
                    cursor: "pointer"
                  }}
                  title={`Trang ${index + 1}`}
                />
              ))}
            </div>
          )}
        </div>
      </div>
    </div>
  );
}

export default ProductList;
